declare(strict_types=1);
function loadEnv(string $file):void{if(!is_file($file))return;foreach(file($file,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)as$line){$line=trim($line);if($line===''||str_starts_with($line,'#')||!str_contains($line,'='))continue;[$key,$value]=explode('=',$line,2);$value=trim($value," \t\n\r\0\x0B\"'");if(getenv(trim($key))===false)putenv(trim($key).'='.$value);}}
loadEnv(dirname(__DIR__).'/.env');$config=require dirname(__DIR__).'/config/app.php';date_default_timezone_set($config['timezone']);ini_set('display_errors',$config['debug']?'1':'0');ini_set('log_errors','1');ini_set('error_log',dirname(__DIR__).'/storage/logs/php.log');
